function CANCELLATION-TEST(E[1..n], d[1..n]):
    levels <- empty map from energy value to running sum
    for i in 1..n:
        v <- representative level of E[i]
        levels[v] <- levels[v] + d[i]
    for each value s in levels:
        if |s| > tol: return FALSE
    return TRUE

function CANCELLATION-CODIMENSION(E[1..n]):
    S <- sort(E)
    count <- 0
    for each e in S:
        if e differs from previous kept value by > tol:
            count <- count + 1
    return count

